<?php
namespace App\Domain\GhostEvents\Models; use App\Domain\Races\Models\RaceRun; use App\Models\User; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class GhostEventAttempt extends Model { protected $fillable=['ghost_event_id','user_id','race_run_id','submission_id','race_session_id','status','is_practice','duration_ms','benchmark_beaten','delta_ms','rank','season_points_awarded','accepted_at']; protected function casts():array{return ['is_practice'=>'boolean','benchmark_beaten'=>'boolean','accepted_at'=>'datetime'];} public function event():BelongsTo{return $this->belongsTo(GhostEvent::class,'ghost_event_id');} public function run():BelongsTo{return $this->belongsTo(RaceRun::class,'race_run_id');} public function user():BelongsTo{return $this->belongsTo(User::class);} }
